#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# factory-repo-setup.sh puts a new repository on the factory with the
# maintainer's own gh login: state and category labels, the
# CLAUDE_CODE_OAUTH_TOKEN secret, the Actions allow-list, the clicks GitHub has
# no API for, then scripts/factory_onboarding_check.py. The labels and the
# allow-list patterns come from scripts/factory_repo_setup.py. Runbook:
# docs/agents/factory-onboarding.md. Tests: test/factory_repo_setup.bats.
# It writes no file: the caller workflows come from the template repo or runbook.

run_wizard() {

TOTAL_STAGES=6

local script_dir repo="" mode="" token_file=""
script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# The token is never read from or written to a dotenv file.
ENV_FILE=/dev/null
factory() { python3 "$script_dir/factory_repo_setup.py" "$@"; }

usage() {
  cat <<'EOF'
Usage: scripts/factory-repo-setup.sh --repo OWNER/NAME [--dry-run | --apply] [--token-file PATH]
Puts a repository on the factory in six stages: preconditions, labels, the
CLAUDE_CODE_OAUTH_TOKEN secret, the Actions allow-list, the clicks without an
API, and the check scripts/factory_onboarding_check.py.
  --repo OWNER/NAME  the target repository (required)
  --dry-run          print every planned write and change nothing (default)
  --apply            perform the writes; asks for the token and the clicks
  --token-file PATH  read the token from PATH instead of hidden entry
  -h, --help         show this help
Needs gh logged in as the maintainer (gh auth login) and python3.
Exit: 0 done (a secret gh could not set is listed at the end),
      2 usage error, 3 a precondition or read failed (gh, login, repo),
      4 a GitHub write failed.
Examples:
  scripts/factory-repo-setup.sh --repo fabiandistler/dotfiles
  scripts/factory-repo-setup.sh --repo fabiandistler/dotfiles --apply
EOF
}

die() {
  printf 'factory-repo-setup.sh: %s\n' "$2" >&2
  exit "$1"
}

dry_run() { [[ "$mode" == dry-run ]]; }
planned() { say "[dry-run] would $1"; }

while (($#)); do
  case "$1" in
    --repo)
      (($# >= 2)) || die 2 "--repo needs OWNER/NAME"
      repo="$2"
      shift 2
      ;;
    --token-file)
      (($# >= 2)) || die 2 "--token-file needs a path"
      token_file="$2"
      shift 2
      ;;
    --dry-run | --apply)
      [[ -z "$mode" || "$mode" == "${1#--}" ]] || die 2 "--dry-run and --apply exclude each other"
      mode="${1#--}"
      shift
      ;;
    -h | --help)
      usage
      return 0
      ;;
    *)
      usage >&2
      die 2 "unknown argument: $1"
      ;;
  esac
done
mode="${mode:-dry-run}"
[[ -n "$repo" ]] || die 2 "--repo OWNER/NAME is required (see --help)"
[[ "$repo" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]] || die 2 "--repo must be OWNER/NAME, got: $repo"
if [[ -n "$token_file" && ! (-f "$token_file" && -r "$token_file" && -s "$token_file") ]]; then
  die 2 "--token-file must name a readable, non-empty file: $token_file"
fi

if dry_run; then
  printf '\nfactory-repo-setup.sh: dry run for %s. Nothing is changed; --apply performs the writes.\n' "$repo"
else
  banner "Factory setup for $repo"
fi

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Preconditions"
command -v gh >/dev/null 2>&1 || die 3 "gh is not installed: https://cli.github.com"
command -v python3 >/dev/null 2>&1 || die 3 "python3 is not installed"
gh auth status >/dev/null 2>&1 || die 3 "gh is not logged in; run: gh auth login"
local visibility
visibility="$(gh api "repos/$repo" --jq .visibility 2>/dev/null)" ||
  die 3 "repository $repo does not exist or this gh login cannot reach it"
say "gh is logged in, and $repo is reachable. Visibility: $visibility."
if [[ "$visibility" == public ]]; then
  note "Public: add a ruleset that requires the checks, and an event policy for"
  note "pull_request_target, by hand (docs/agents/factory-onboarding.md, step 5)."
else
  warn "Private on GitHub Free: no ruleset, so no check can be required (rulesets"
  warn "need Pro). Brakes: the push guard and merging only on green."
fi

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Labels"
local wanted existing label
local -a missing_labels=()
wanted="$(factory labels)"
existing="$(gh api --paginate "repos/$repo/labels?per_page=100" --jq '.[].name')" ||
  die 3 "could not list the labels of $repo"
while IFS= read -r label; do
  # GitHub compares label names case-insensitively.
  if grep -qixF -- "$label" <<<"$existing"; then
    note "exists, left as it is: $label"
  else
    missing_labels+=("$label")
  fi
done <<<"$wanted"
for label in "${missing_labels[@]}"; do
  if dry_run; then
    planned "create label $label"
  else
    gh api -X POST "repos/$repo/labels" -f name="$label" >/dev/null ||
      die 4 "could not create label $label"
    say "${GREEN}✓ created${RESET} label $label"
  fi
done
((${#missing_labels[@]})) || say "All labels exist; nothing to create."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Secret CLAUDE_CODE_OAUTH_TOKEN"
note "The token comes from \`claude setup-token\` (valid one year; pr-review-runbook.md, Setup)."
local secret_names secret_exists=no source_name="hidden entry"
[[ -z "$token_file" ]] || source_name="the file $token_file"
secret_names="$(gh api --paginate "repos/$repo/actions/secrets?per_page=100" --jq '.secrets[].name')" ||
  die 3 "could not list the Actions secrets of $repo (needs admin rights on it)"
grep -qxF CLAUDE_CODE_OAUTH_TOKEN <<<"$secret_names" && secret_exists=yes
if dry_run; then
  if [[ "$secret_exists" == yes ]]; then
    say "The secret exists. --apply asks before replacing it with the token from $source_name."
  else
    planned "set secret CLAUDE_CODE_OAUTH_TOKEN from $source_name"
  fi
elif [[ "$secret_exists" == yes ]] && ! confirm "CLAUDE_CODE_OAUTH_TOKEN is already set. Replace it?"; then
  note "Kept the existing secret."
else
  local CLAUDE_CODE_OAUTH_TOKEN=""
  if [[ -n "$token_file" ]]; then
    CLAUDE_CODE_OAUTH_TOKEN="$(<"$token_file")"
    CLAUDE_CODE_OAUTH_TOKEN="${CLAUDE_CODE_OAUTH_TOKEN%$'\r'}"
  else
    step "Run \`claude setup-token\` in another terminal and copy the token."
    ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token (hidden):" || die 2 "no token entered"
  fi
  [[ -n "$CLAUDE_CODE_OAUTH_TOKEN" ]] || die 2 "the token is empty"
  # On stdin, never in argv. set_secret would hide a failure as "skipped".
  printf '%s' "$CLAUDE_CODE_OAUTH_TOKEN" | gh secret set CLAUDE_CODE_OAUTH_TOKEN --repo "$repo" >/dev/null ||
    die 4 "could not set secret CLAUDE_CODE_OAUTH_TOKEN"
  CLAUDE_CODE_OAUTH_TOKEN=""
  WRITTEN_SECRET+=(CLAUDE_CODE_OAUTH_TOKEN)
  say "${GREEN}✓ set${RESET} GitHub secret CLAUDE_CODE_OAUTH_TOKEN"
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Actions allow-list"
local allowed_actions selected_actions pattern
local -a missing_patterns=()
allowed_actions="$(gh api "repos/$repo/actions/permissions" --jq .allowed_actions)" ||
  die 3 "could not read the Actions permissions of $repo"
if [[ "$allowed_actions" != selected ]]; then
  say "Allowed actions: ${allowed_actions:-unset}. Not restricted to a selected list,"
  say "so the policy is left unchanged."
else
  selected_actions="$(gh api "repos/$repo/actions/permissions/selected-actions")" ||
    die 3 "could not read the selected actions of $repo"
  while IFS= read -r pattern; do
    [[ -z "$pattern" ]] || missing_patterns+=("$pattern")
  done < <(factory missing-patterns <<<"$selected_actions")
  if ((${#missing_patterns[@]} == 0)); then
    say "The selected list already allows every factory pattern; nothing to add."
  elif dry_run; then
    for pattern in "${missing_patterns[@]}"; do planned "allow $pattern"; done
  else
    factory allowlist-body <<<"$selected_actions" |
      gh api -X PUT "repos/$repo/actions/permissions/selected-actions" --input - >/dev/null ||
      die 4 "could not update the selected actions of $repo"
    for pattern in "${missing_patterns[@]}"; do say "${GREEN}✓ allowed${RESET} $pattern"; done
  fi
fi

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Clicks without an API"
local app_url="https://github.com/$repo/settings/installations"
local dependabot_url="https://github.com/$repo/settings/security_analysis"
say "Claude GitHub App"
if dry_run; then say "[dry-run] --apply opens $app_url"; else open_url "$app_url"; fi
step "Under \"Installed GitHub Apps\", Claude must be listed. If it is: done."
step "If not: open https://github.com/apps/claude → Install (or Configure) →"
step "  Repository access → \"All repositories\" → Install / Save."
if ! dry_run && ! confirm "Does the Claude GitHub App cover $repo?"; then
  SKIPPED+=("Claude GitHub App on $repo: $app_url")
fi
printf '\n'
say "Dependabot runner type"
if dry_run; then say "[dry-run] --apply opens $dependabot_url"; else open_url "$dependabot_url"; fi
step "Dependabot version updates → Runner type → Standard GitHub runner"
step "Click \"Save runner selection\"."
step "Reload the page and check that Standard GitHub runner is still selected:"
step "  the first save may not take."
if ! dry_run && ! confirm "After the reload, is Standard GitHub runner selected?"; then
  SKIPPED+=("Dependabot runner type on $repo: $dependabot_url")
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Verify"
local gh_token check_status=0
gh_token="$(gh auth token)" || die 3 "gh auth token printed no token"
say "python3 scripts/factory_onboarding_check.py --repo $repo"
GH_TOKEN="$gh_token" python3 "$script_dir/factory_onboarding_check.py" --repo "$repo" || check_status=$?
gh_token=""
case "$check_status" in
  0) say "No MISSING line." ;;
  1) warn "Act on every MISSING line above; caller files come from the template or the runbook." ;;
  *) warn "The check could not run to the end (exit $check_status); see its message above." ;;
esac
note "CANNOT-VERIFY for the App, the secret and the policy: stages 3 to 5 covered them."

if dry_run; then
  printf '\nDry run: nothing changed. Re-run with --apply to perform the writes above.\n'
else
  finish
fi
}

run_wizard "$@"; exit
